/**
 * @name Unsafe exec in optimize
 * @description Tracing data flow to exec calls in optimize module.
 * @kind path-problem
 * @problem.severity error
 * @id py/scipy-optimize-exec-trace
 * @tags security
 *       external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module OptimizeExecTraceConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("exec").getACall()
      |
      sink = call.getArg(0)
    )
  }
}

module OptimizeExecTraceFlow = TaintTracking::Global<OptimizeExecTraceConfig>;
import OptimizeExecTraceFlow::PathGraph

from OptimizeExecTraceFlow::PathNode source, OptimizeExecTraceFlow::PathNode sink
where OptimizeExecTraceFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Exec call from $@.", source.getNode(), "parameter"

/**
 * @name Trace flow to eval in optimize/_nonlin.py
 * @description Traces flow from function parameters to eval in scipy/optimize/_nonlin.py
 * @kind path-problem
 * @problem.severity error
 * @id py/scipy-optimize-eval-trace
 * @tags security
 *       external/cwe/cwe-095
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking

module OptimizeEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(Call call |
      call.getFunc().(Name).getId() = "eval" or
      call.getFunc().(Name).getId() = "exec" |
      sink.asExpr() = call.getArg(0)
    )
    and sink.getLocation().getFile().getShortName() = "_nonlin.py"
  }
}

module OptimizeEvalFlow = TaintTracking::Global<OptimizeEvalConfig>;
import OptimizeEvalFlow::PathGraph

from OptimizeEvalFlow::PathNode source, OptimizeEvalFlow::PathNode sink
where OptimizeEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection in optimize/_nonlin.py from parameter $@.", source.getNode(), source.getNode().toString()
